//! Parity with the committed contracts from the original web app (`tests/fixtures`, copied from
//! the Laravel repo). These fixtures were generated by the TypeScript implementation that the
//! editor shipped with; the Rust port must reproduce them exactly.

use std::collections::BTreeMap;

use serde_json::Value;
use woodshop_core::geometry::outline::{self, Segment};
use woodshop_core::spec::{Curve, Notch, Op};
use woodshop_core::units::format_fraction;

fn fixture(name: &str) -> Value {
    let path = format!("{}/tests/fixtures/{name}", env!("CARGO_MANIFEST_DIR"));
    serde_json::from_str(&std::fs::read_to_string(&path).expect(&path)).expect(&path)
}

#[test]
fn fractions_match_contract() {
    let cases: BTreeMap<String, String> = serde_json::from_value(fixture("fraction-cases.json")).unwrap();
    for (input, expected) in cases {
        let value: f64 = input.parse().unwrap();
        assert_eq!(format_fraction(value, 16), expected, "format_fraction({input})");
    }
}

/// Fixed-decimal so the two runtimes cannot disagree on a last bit. -0 normalises to 0.
fn outline_num(v: f64) -> String {
    if !v.is_finite() {
        return if v.is_nan() {
            "NaN".into()
        } else if v > 0.0 {
            "Infinity".into()
        } else {
            "-Infinity".into()
        };
    }
    let rounded = (v * 1e9).round() / 1e9;
    let rounded = if rounded == 0.0 { 0.0 } else { rounded };
    format!("{rounded:.9}")
}

fn fingerprint(s: &Segment) -> String {
    match s {
        Segment::Line { x, y, .. } => format!("line|{}|{}", outline_num(*x), outline_num(*y)),
        Segment::Arc {
            cx,
            cy,
            r,
            a0,
            a1,
            clockwise,
            ..
        } => format!(
            "arc|{}|{}|{}|{}|{}|{clockwise}",
            outline_num(*cx),
            outline_num(*cy),
            outline_num(*r),
            outline_num(*a0),
            outline_num(*a1)
        ),
    }
}

#[test]
fn outlines_match_contract() {
    let cases = fixture("outline-cases.json");
    let expected = fixture("outline-expected.json");
    let cases = cases.as_object().unwrap();
    assert!(!cases.is_empty());
    let mut failures = Vec::new();

    for (name, case) in cases {
        let ops: Vec<Op> = serde_json::from_value(case["ops"].clone()).unwrap_or_else(|e| panic!("{name}: {e}"));
        let curves: Vec<Curve> = ops
            .iter()
            .filter_map(|o| if let Op::Curve(c) = o { Some(c.clone()) } else { None })
            .collect();
        let notches: Vec<Notch> = ops
            .iter()
            .filter_map(|o| if let Op::Notch(n) = o { Some(n.clone()) } else { None })
            .collect();
        let actual: Vec<String> = outline::build(
            case["l"].as_f64().unwrap(),
            case["w"].as_f64().unwrap(),
            &curves,
            &notches,
        )
        .segments
        .iter()
        .map(fingerprint)
        .collect();
        let want: Vec<String> = serde_json::from_value(expected[name].clone()).unwrap_or_default();
        if actual != want {
            failures.push(format!("{name}:\n  want {want:?}\n  got  {actual:?}"));
        }
    }
    assert!(
        failures.is_empty(),
        "{} of {} outline cases differ:\n{}",
        failures.len(),
        cases.len(),
        failures.join("\n")
    );
}

fn round3(v: &mut Value) {
    match v {
        Value::Number(n) => {
            let f = n.as_f64().unwrap();
            let r = (f * 1000.0).round() / 1000.0;
            *v = serde_json::json!(r);
        }
        Value::Array(a) => a.iter_mut().for_each(round3),
        Value::Object(o) => o.values_mut().for_each(round3),
        _ => {}
    }
}

/// Numbers compared by value, so `285` and `285.0` agree.
fn numeric_eq(a: &Value, b: &Value) -> bool {
    match (a, b) {
        (Value::Number(x), Value::Number(y)) => (x.as_f64().unwrap() - y.as_f64().unwrap()).abs() < 1e-9,
        (Value::Array(x), Value::Array(y)) => x.len() == y.len() && x.iter().zip(y).all(|(a, b)| numeric_eq(a, b)),
        (Value::Object(x), Value::Object(y)) => {
            x.len() == y.len() && x.iter().all(|(k, v)| y.get(k).is_some_and(|w| numeric_eq(v, w)))
        }
        _ => a == b,
    }
}

fn load_spec(file: &str) -> woodshop_core::spec::Spec {
    let raw = fixture(&format!("specs/{file}"));
    let migrated = woodshop_core::spec::migrate_to_latest(raw).unwrap();
    woodshop_core::spec::from_value(migrated).unwrap()
}

#[test]
fn cut_lists_match_golden_snapshots() {
    use woodshop_core::cutlist::{CutListConfig, compute_cut_list};
    let expected = fixture("cutlist-expected.json");
    for (name, file) in [
        ("record-stand", "record-stand.spec.json"),
        ("bookshelf", "bookshelf.spec.json"),
    ] {
        let spec = load_spec(file);
        let mut actual = serde_json::to_value(compute_cut_list(&spec, CutListConfig::default())).unwrap();
        round3(&mut actual);
        assert!(
            numeric_eq(&actual, &expected[name]),
            "{name} cut list differs:\nwant {}\ngot  {}",
            serde_json::to_string_pretty(&expected[name]).unwrap(),
            serde_json::to_string_pretty(&actual).unwrap()
        );
    }
}

#[test]
fn lint_matches_contract() {
    let cases = fixture("lint-cases.json");
    let expected = fixture("lint-expected.json");

    let mut corpus: Vec<(String, Value)> = cases
        .as_object()
        .unwrap()
        .iter()
        .map(|(k, v)| (format!("case:{k}"), v.clone()))
        .collect();
    let templates = format!("{}/../../resources/templates", env!("CARGO_MANIFEST_DIR"));
    let mut paths: Vec<_> = std::fs::read_dir(&templates)
        .unwrap()
        .map(|e| e.unwrap().path())
        .collect();
    paths.sort();
    for path in paths {
        let name = path.file_stem().unwrap().to_string_lossy().to_string();
        corpus.push((
            format!("template:{name}"),
            serde_json::from_str(&std::fs::read_to_string(&path).unwrap()).unwrap(),
        ));
    }

    let mut failures = Vec::new();
    for (name, raw) in &corpus {
        let migrated = woodshop_core::spec::migrate_to_latest(raw.clone()).unwrap();
        let spec: woodshop_core::spec::Spec = match woodshop_core::spec::from_value(migrated) {
            Ok(s) => s,
            Err(e) => {
                failures.push(format!("{name}: does not parse: {e}"));
                continue;
            }
        };
        let mut keys: Vec<String> = woodshop_core::lint::lint(&spec).iter().map(|i| i.identity()).collect();
        keys.sort();
        let want: Vec<String> =
            serde_json::from_value(expected[name].clone()).unwrap_or_else(|_| vec!["<missing>".into()]);
        if keys != want {
            failures.push(format!("{name}:\n  want {want:?}\n  got  {keys:?}"));
        }
    }
    assert!(
        failures.is_empty(),
        "{} of {} lint cases differ:\n{}",
        failures.len(),
        corpus.len(),
        failures.join("\n")
    );
}
